after.content:
    try (var context = new AnnotationConfigApplicationContext()) {
        context.getEnvironment().getPropertySources().addFirst(
                new org.springframework.core.env.MapPropertySource("test", Map.of("ji.host.enabled", "true")));
        context.registerBean("customJiHost", LocalHostApplication.class, () -> null);
        context.register(JiHostAutoConfiguration.class);
        context.refresh();
        assertTrue(context.containsBeanDefinition("customJiHost"));
        assertFalse(context.containsBean("jiLocalHostApplication"));
    }
}
